package com.bank.fallback.resilience;

import java.util.concurrent.Semaphore;

// Bounds how many calls can hit the fallback dependency at once.
// Excess is REJECTED (load shed) rather than queued or passed through.
public class Bulkhead {
    private final Semaphore permits;
    public Bulkhead(int maxConcurrent) { this.permits = new Semaphore(maxConcurrent); }
    public boolean tryAcquire() { return permits.tryAcquire(); }
    public void release() { permits.release(); }
    public int available() { return permits.availablePermits(); }
}
