package com.bank.fallback.resilience;

import java.util.concurrent.atomic.AtomicInteger;

// Opens after N consecutive primary failures so we stop hammering a dead primary.
public class CircuitBreaker {
    private final int threshold;
    private final AtomicInteger consecutiveFailures = new AtomicInteger();
    private volatile boolean open = false;
    public CircuitBreaker(int threshold) { this.threshold = threshold; }
    public boolean isOpen() { return open; }
    public void recordSuccess() { consecutiveFailures.set(0); open = false; }
    public void recordFailure() {
        if (consecutiveFailures.incrementAndGet() >= threshold) open = true;
    }
}
