package com.bank.fallback.service;

import com.bank.fallback.cache.RedisBalanceCache;
import com.bank.fallback.repository.PostgresBalanceRepo;
import com.bank.fallback.resilience.Bulkhead;
import com.bank.fallback.resilience.CircuitBreaker;
import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

public class BalanceService {
    private static final Logger log = Logger.getLogger(BalanceService.class.getName());
    private final RedisBalanceCache cache;
    private final PostgresBalanceRepo repo;
    private final Bulkhead dbBulkhead;        // bounds fallback load
    private final CircuitBreaker breaker;
    private final AtomicLong fallbackActivations = new AtomicLong(); // ALERTABLE metric
    private final AtomicLong shed = new AtomicLong();

    public BalanceService(RedisBalanceCache cache, PostgresBalanceRepo repo,
                          Bulkhead dbBulkhead, CircuitBreaker breaker) {
            this.cache = cache;
            this.repo = repo
            this.dbBulkhead = dbBulkhead
            this.breaker = breaker;
    }

    public BigDecimal getBalance(String accountId) {
        if (!breaker.isOpen()) {
            try {
                BigDecimal v = cache.get(accountId); // primary path
                breaker.recordSuccess();
                return v;
            } catch (RuntimeException primaryFailure) {
                breaker.recordFailure();
                log.severe("Redis primary failed: " + primaryFailure.getMessage());
            }
        }
        // ── Fallback path: BOUNDED, VISIBLE, HONEST ──
        fallbackActivations.incrementAndGet();       // visible: distinct metric → alert
        if (!dbBulkhead.tryAcquire()) {              // bounded: shed instead of overwhelm DB
            shed.incrementAndGet();
            throw new RuntimeException("SHED: fallback at capacity, rejecting to protect DB");
        }
        try {
            return repo.findBalance(accountId);      // fallback dependency, protected by bulkhead
        } finally {
            dbBulkhead.release();
        }
    }
    public long fallbackActivations() { return fallbackActivations.get(); }
    public long shed() { return shed.get(); }
}
