package com.bank.fallback;

import com.bank.fallback.cache.RedisBalanceCache;
import com.bank.fallback.repository.PostgresBalanceRepo;
import com.bank.fallback.resilience.Bulkhead;
import com.bank.fallback.resilience.CircuitBreaker;
import com.bank.fallback.service.BalanceService;
import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class FallbackDemo {
    private static final Logger log = Logger.getLogger(FallbackDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) throws Exception {
        RedisBalanceCache cache = new RedisBalanceCache();
        cache.put("SAV2001", new BigDecimal("1000000"));
        cache.fail(true); // simulate full Redis outage

        PostgresBalanceRepo repo = new PostgresBalanceRepo();
        repo.put("SAV2001", new BigDecimal("1000000"));

        Bulkhead dbBulkhead = new Bulkhead(5);        // DB only sized for 5 concurrent
        CircuitBreaker breaker = new CircuitBreaker(3);
        BalanceService svc = new BalanceService(cache, repo, dbBulkhead, breaker);

        // 50 concurrent requests all hit the fallback because Redis is down.
        ExecutorService pool = Executors.newFixedThreadPool(50);
        for (int i = 0; i < 50; i++) {
            pool.submit(() -> {
                try { svc.getBalance("SAV2001"); }
                catch (RuntimeException e) { /* shed — DB protected */ }
            });
        }
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        log.warning(() -> "Fallback activations=" + svc.fallbackActivations() + " (ALERT should fire)");
        log.info(() -> "Requests shed to protect DB=" + svc.shed());
        log.info("DB survived because bulkhead capped concurrency at 5");
    }
}

