package com.bank.fallback.cache;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class RedisBalanceCache {
    private final Map<String, BigDecimal> store = new HashMap<>();
    private volatile boolean failing = false;
    public void put(String id, BigDecimal v) { store.put(id, v); }
    public void fail(boolean f) { this.failing = f; }
    public BigDecimal get(String id) {
        if (failing) throw new RuntimeException("Redis connection refused");
        return store.get(id);
    }
}
